if (element.nextElementSibling && element.nextElementSibling.classList.contains('cta-button-wrapper')) return;

const wrapper = document.createElement('div');
wrapper.className = 'cta-button-wrapper';
wrapper.style.cssText = 'margin-top: 16px; margin-bottom: 8px; text-align: center;';

const btn = document.createElement('a');
btn.href = 'https://support.fandom.com/hc/en-us/requests/new';
btn.textContent = 'Contact Us for Assistance';
btn.style.cssText = 'display: inline-block; padding: 12px 32px; background-color: #1dbf73; color: #fff; font-size: 16px; font-weight: bold; text-decoration: none; border-radius: 8px; cursor: pointer; transition: background-color 0.2s ease; box-shadow: 0 2px 8px rgba(0,0,0,0.15);';

btn.addEventListener('mouseover', function() { btn.style.backgroundColor = '#19a463'; });
btn.addEventListener('mouseout', function() { btn.style.backgroundColor = '#1dbf73'; });

wrapper.appendChild(btn);
element.parentNode.insertBefore(wrapper, element.nextSibling);
